        date_sent3: NOT_GIVEN,
        page_size: NOT_GIVEN,
        page: NOT_GIVEN,
        page_token: NOT_GIVEN,
        request_options: nil
      )

        Validation.validate_length('AccountSid', account_sid, min: 34, max: 34)
        Validation.validate_pattern('AccountSid', account_sid, '^AC[0-9a-fA-F]{32}$')

        Validation.if_given(date_sent) { Validation.validate_date_time('DateSent', date_sent) }

        Validation.if_given(date_sent2) { Validation.validate_date_time('DateSent<', date_sent2) }

        Validation.if_given(date_sent3) { Validation.validate_date_time('DateSent>', date_sent3) }

        Validation.if_given(page_size) { Validation.validate_range('PageSize', page_size, min: 1, max: 1000) }

        Validation.if_given(page) { Validation.validate_range('Page', page, min: 0) }

        SdkClient.request(
          'GET',
          [
            "/2010-04-01/Accounts/",
            SdkClient.encode_path_segment(account_sid),
            "/Messages.json"
          ].join,
          config: config,
          query: {
            'To' => QueryValue.new(to, style: 'form', explode: true),
            'From' => QueryValue.new(from, style: 'form', explode: true),
            'DateSent' => QueryValue.new(date_sent, style: 'form', explode: true),
            'DateSent<' => QueryValue.new(date_sent2, style: 'form', explode: true),
            'DateSent>' => QueryValue.new(date_sent3, style: 'form', explode: true),
            'PageSize' => QueryValue.new(page_size, style: 'form', explode: true),
            'Page' => QueryValue.new(page, style: 'form', explode: true),
            'PageToken' => QueryValue.new(page_token, style: 'form', explode: true),
          },
          return_type: ::OctridevTwilio::Methods::Messages::ListMessagesResponse,
          decoder: :json,
          operation_id: 'list_messages',
          request_options: request_options,
        ).data
      end
    end
  end
end

